import{describe,it,expect,beforeEach}from"vitest";import{BudgetCalculatorEngine}from"../../frontend/js-modules/budget-calculator-engine.js";describe("BudgetCalculatorEngine",()=>{let e;beforeEach(()=>{e=new BudgetCalculatorEngine({totalBudget:1e4,currency:"INR"})}),it("should initialize budget and empty expenses",()=>{expect(e.totalBudget).toBe(1e4),expect(e.getTotalSpent()).toBe(0),expect(e.getRemainingBudget()).toBe(1e4)}),it("should add valid expenses and update total spent",()=>{const t=e.addExpense("Hotel Stay",4e3,"lodging");expect(t).not.toBeNull(),expect(e.getTotalSpent()).toBe(4e3),expect(e.getRemainingBudget()).toBe(6e3)}),it("should reject invalid expenses",()=>{expect(e.addExpense("",500)).toBeNull(),expect(e.addExpense("Food",-100)).toBeNull()}),it("should calculate category breakdown",()=>{e.addExpense("Hotel",3e3,"lodging"),e.addExpense("Train",1e3,"transport"),e.addExpense("Taxi",500,"transport");const t=e.getCategoryBreakdown();expect(t.lodging).toBe(3e3),expect(t.transport).toBe(1500)}),it("should reflect correct budget health status",()=>{expect(e.getBudgetHealth().status).toBe("healthy"),e.addExpense("Resort",9e3,"lodging"),expect(e.getBudgetHealth().status).toBe("warning"),e.addExpense("Shopping",2e3,"misc"),expect(e.getBudgetHealth().status).toBe("exceeded")}),it("should format INR currency properly",()=>{expect(e.formatCurrency(5e3)).toBe("₹5,000")})});